// Generate unique IDs starting from 701 to avoid conflicts
function generatePlayers() {
  const players = [];
  let id = 701; // Start from 701 to avoid conflicts with existing players

  for (const player of post2020Players) {
    players.push({
      id: String(id++),
      name: player.name,
      debutYear: player.debut,
      nation: player.nation,
      intlMatches: player.intlMatches,
      runs: player.runs,
      wickets: player.wickets,
      battingHand: player.battingHand,
      bowlingType: player.bowlingType,
      highScore: player.highScore,
      teams: player.teams
    });
  }

  return players;
}

// Generate and output players
const players = generatePlayers();

console.log(`Generated ${players.length} post-2020 international cricket players\n`);

// Show distribution by nation
const nationCounts = {};
players.forEach(p => {
  nationCounts[p.nation] = (nationCounts[p.nation] || 0) + 1;
});
console.log('Distribution by nation:');
Object.entries(nationCounts).sort((a, b) => b[1] - a[1]).forEach(([nation, count]) => {
  console.log(`  ${nation}: ${count} players`);
});

// Show sample players
console.log('\nSample players:');
players.slice(0, 5).forEach(p => {
  console.log(`  ${p.name} (${p.nation}) - Debut: ${p.debutYear}, Matches: ${p.intlMatches}, Runs: ${p.runs}, Wickets: ${p.wickets}`);
});

// Output TypeScript code to append to cricketers.ts
console.log('\n=== TypeScript Data (copy to lib/cricketers.ts) ===\n');

const tsOutput = players.map(p => `  {
    id: "${p.id}",
    name: "${p.name}",
    debutYear: ${p.debutYear},
    nation: "${p.nation}",
    intlMatches: ${p.intlMatches},
    runs: ${p.runs},
    wickets: ${p.wickets},
    battingHand: "${p.battingHand}",
    bowlingType: "${p.bowlingType}",
    highScore: ${p.highScore},
    teams: ${JSON.stringify(p.teams)}
  }`).join(',\n');

console.log('// Add these players to the cricketers array:\n');
console.log(tsOutput);

console.log(`\n\nTotal: ${players.length} players generated`);
